    function OnClickSaveEditing() {
        Variable.SetValueAsString("SendOption", JSON.stringify({
            sendOption: "POEdit_EmailToVendor",
            email: Data.GetValue("VendorEmail__")
        }));
        Lib.Purchasing.PO.Edition.ChangesManager.Serialize();
